        },
        {
          "const": "animus:play-recording",
          "description": "Replaces the NPC's route with a recording it walks to and plays once, in a loop (the default) or back and forth. With wait, a once playback completes when it ends."
        },
        {
          "const": "animus:play-sound",
          "description": "Plays a sound at the NPC, or with at: player at the player, for the triggering player or nearby players. Server behaviors play at the player."
        },
        {
          "const": "animus:pose",
          "description": "Turns the NPC to one of the named poses in its definition's poses."
        },
        {
          "const": "animus:resume-patrol",
          "description": "Restarts the route or recording the NPC's definition declares; a stopped recording continues where it stopped. Reports resumed or nothing-to-resume."
        },
        {
          "const": "animus:say",
          "description": "Sends dialogue text to the triggering player, the player named by player, or nearby players; {player_name} becomes that player's name."
        },
        {
          "const": "animus:set-appearance",
          "description": "Changes the NPC's displayed name or skin until the runtime restarts or its definition changes."
        },
        {
          "const": "animus:set-equipment",
          "description": "Shows an item in an equipment slot, or clears the slot when no item is given. Lasts until the runtime restarts or the definition changes."
        },
        {
          "const": "animus:set-flag",
          "description": "Sets a flag to value (true by default: any JSON value), optionally for expireSeconds; clear: true unsets it."
        },
        {
          "const": "animus:set-quest-state",
          "description": "Sets a quest stage to value, or to a random stage from zero to below random."
        },
        {
          "const": "animus:spawn-particle",
          "description": "Shows a particle effect at the NPC, or with at: player at the player, to the triggering player or nearby players. Server behaviors show it at the player."
        },
        {
          "const": "animus:stop-animation",
          "description": "Stops one animation layer, or every played layer, and returns to the rig's idle animation."
        },
        {
          "const": "animus:stop-navigation",
          "description": "Stops the NPC's current route and any route it is following."
        },
        {
          "const": "animus:take-item",
