      "allOf": [
        {
          "if": {
            "properties": {
              "type": {
                "const": "text"
              }
            }
          },
          "then": {
            "$ref": "#/$defs/textIcon"
          }
        },
        {
          "if": {
            "properties": {
              "type": {
                "const": "textImage"
              }
            }
          },
          "then": {
            "$ref": "#/$defs/textImageIcon"
          }
        },
        {
          "if": {
            "properties": {
              "type": {
                "const": "animatedTextImage"
              }
            }
          },
          "then": {
            "$ref": "#/$defs/animatedTextImageIcon"
          }
        },
        {
          "if": {
            "properties": {
              "type": {
                "const": "item"
              }
            }
          },
          "then": {
            "$ref": "#/$defs/itemIcon"
          }
        },
        {
          "if": {
            "properties": {
              "type": {
                "const": "block"
              }
            }
          },
          "then": {
            "$ref": "#/$defs/blockIcon"
          }
        },
        {
          "if": {
            "properties": {
              "type": {
                "const": "customItem"
              }
            }
          },
          "then": {
            "$ref": "#/$defs/customItemIcon"
          }
        },
        {
          "if": {
            "properties": {
              "type": {
                "const": "entity"
              }
            }
          },
          "then": {
            "allOf": [
              {
                "$ref": "#/$defs/entityIcon"
              },
              {
                "not": {
                  "required": [
                    "style"
                  ]
                }
              }
            ]
          }
        },
        {
          "if": {
            "properties": {
              "type": {
                "const": "playerHead"
              }
            }
          },
          "then": {
            "$ref": "#/$defs/playerHeadIcon"
          }
        }
      ]
    },
    "hitbox": {
