      "required": [
        "actions",
        "icon"
      ],
      "properties": {
        "highlightModifier": {
          "description": "Menu-local travel toward the viewer at uiScale 1.",
          "type": "number"
        },
        "hoverDurationTicks": {
          "description": "Ticks used to enter and leave the hovered pose. Defaults to 4; zero is instant.",
          "type": "integer",
          "minimum": 0,
          "maximum": 40
        },
        "hoverEasing": {
          "description": "Easing curve used for hover entry and exit. Defaults to ease_out_cubic.",
          "type": "string",
          "enum": [
            "linear",
            "ease_out_cubic",
            "ease_in_out_cubic",
            "back_out"
          ]
        },
        "actions": {
          "description": "Defines what happens upon a interaction.",
          "type": "array",
          "items": {
