    "messageAction": {
      "title": "Player Message Action Data Object",
      "description": "Sends a MiniMessage-formatted message to the clicking player.",
      "type": "object",
      "required": [
        "message"
      ],
      "properties": {
        "message": {
          "description": "MiniMessage text sent to the player. %player% and PlaceholderAPI placeholders are resolved for the clicking player before parsing.",
          "type": "string",
          "minLength": 1,
          "pattern": "\\S"
        }
      }
    },
    "teleportAction": {
      "title": "Player Teleport Action Data Object",
      "description": "Teleports the clicking player asynchronously to an already-loaded namespaced world.",
      "type": "object",
      "required": [
        "world",
        "x",
        "y",
        "z",
        "yaw",
        "pitch"
      ],
      "properties": {
        "world": {
          "description": "Explicit lowercase namespace:key of an already-loaded Bukkit world.",
          "type": "string",
          "maxLength": 255,
          "pattern": "^[a-z0-9._-]+:[a-z0-9/._-]+$"
        },
        "x": {
          "description": "Finite destination X coordinate.",
          "type": "number"
        },
        "y": {
          "description": "Finite destination Y coordinate.",
          "type": "number"
        },
        "z": {
          "description": "Finite destination Z coordinate.",
          "type": "number"
        },
        "yaw": {
          "description": "Finite destination yaw in degrees.",
          "type": "number"
        },
        "pitch": {
          "description": "Finite destination pitch in degrees.",
          "type": "number"
        }
      }
    },
    "connectAction": {
      "title": "Proxy Server Connect Action Data Object",
      "description": "Requests a BungeeCord-compatible proxy connection for the clicking player.",
      "type": "object",
      "required": [
        "server"
      ],
      "properties": {
        "server": {
          "description": "Configured proxy server name. Only letters, numbers, dot, underscore, and hyphen are accepted.",
          "type": "string",
          "minLength": 1,
          "maxLength": 64,
          "pattern": "^[A-Za-z0-9][A-Za-z0-9._-]{0,63}$"
        }
      }
    },
    "titleAction": {
      "title": "Title Action Data Object",
      "description": "Shows a title and subtitle to the clicking player through the shared HUD compositor, so a higher-priority title from another plugin is not overwritten. Continues the action list.",
      "type": "object",
      "required": [
        "title"
      ],
      "properties": {
        "title": {
          "description": "Title text. Runs through the full text pipeline for the clicking player.",
          "type": "string",
          "minLength": 1,
          "pattern": "\\S"
        },
        "subtitle": {
          "description": "Optional subtitle text under the title. Omitted means no subtitle.",
          "type": "string"
        },
        "fadeInTicks": {
          "description": "Ticks the title fades in over. Defaults to 10.",
          "type": "integer",
          "minimum": 0,
          "maximum": 1200
        },
        "stayTicks": {
          "description": "Ticks the title stays fully visible. Defaults to 40.",
          "type": "integer",
          "minimum": 0,
          "maximum": 1200
        },
        "fadeOutTicks": {
          "description": "Ticks the title fades out over. Defaults to 10.",
          "type": "integer",
          "minimum": 0,
          "maximum": 1200
        },
        "priority": {
          "description": "Compositor priority this title bids with. Defaults to notice.",
          "type": "string",
          "enum": [
            "ambient",
            "notice",
            "status",
            "progress",
            "interactive",
            "modal",
            "pinned"
          ]
        }
      }
    },
    "actionBarAction": {
      "title": "Action Bar Action Data Object",
      "description": "Publishes one action bar segment for the clicking player through the shared HUD compositor, which merges it with segments other plugins publish. Continues the action list.",
      "type": "object",
      "required": [
        "text"
      ],
      "properties": {
        "text": {
          "description": "Action bar text. Runs through the full text pipeline for the clicking player.",
          "type": "string",
          "minLength": 1,
          "pattern": "\\S"
        },
        "ticks": {
          "description": "Ticks the segment stays published before it expires. Defaults to 60.",
          "type": "integer",
          "minimum": 1,
          "maximum": 1200
        },
        "slots": {
          "description": "Compositor slots this segment may occupy. Defaults to center.",
          "type": "array",
          "items": {
            "type": "string",
            "enum": [
              "left",
              "center",
              "right"
            ]
          }
        },
        "priority": {
          "description": "Compositor priority this segment bids with. Defaults to notice.",
          "type": "string",
          "enum": [
            "ambient",
            "notice",
            "status",
            "progress",
            "interactive",
            "modal",
            "pinned"
          ]
        }
      }
    },
    "bossBarAction": {
      "title": "Boss Bar Action Data Object",
      "description": "Shows or hides one boss bar lane for the clicking player through the shared HUD compositor, which caps how many bars a viewer sees at once. Continues the action list.",
      "type": "object",
      "required": [
        "id",
        "title"
      ],
      "properties": {
        "id": {
          "description": "Lane id for this bar. Reusing the id replaces the bar instead of adding a second one.",
          "type": "string",
          "minLength": 1,
          "pattern": "\\S"
        },
        "title": {
          "description": "Bar title. Runs through the full text pipeline for the clicking player.",
          "type": "string",
          "minLength": 1,
          "pattern": "\\S"
        },
        "progress": {
          "description": "Fill from 0 to 1 as a literal number in a string. Defaults to 1.",
          "type": "string"
        },
        "color": {
          "description": "Bar color. Defaults to white.",
          "type": "string",
          "enum": [
            "pink",
            "blue",
            "red",
            "green",
            "yellow",
            "purple",
            "white"
          ]
        },
        "style": {
          "description": "Bar segmentation. Defaults to solid.",
          "type": "string",
          "enum": [
            "solid",
            "segmented_6",
            "segmented_10",
            "segmented_12",
            "segmented_20"
          ]
        },
        "ticks": {
          "description": "Ticks the bar stays asserted before it expires. 0 hides the lane instead of showing it. Defaults to 100.",
          "type": "integer",
          "minimum": 0,
          "maximum": 1200
        },
        "priority": {
          "description": "Compositor priority this bar bids with. Defaults to notice.",
          "type": "string",
          "enum": [
            "ambient",
            "notice",
            "status",
            "progress",
            "interactive",
            "modal",
            "pinned"
          ]
        }
      }
    },
    "navigationAction": {
      "title": "Navigation Action Data Object",
      "description": "Changes the current viewer's native menu page stack. Navigation is terminal for actions matching the current click trigger.",
      "type": "object",
      "properties": {
        "target": {
          "description": "Exact menu id opened by push or replace navigation.",
          "type": "string",
          "minLength": 1,
          "pattern": "\\S"
        },
        "mode": {
          "description": "Page-stack operation. Defaults to push.",
          "type": "string",
          "enum": [
            "push",
            "replace",
            "back",
            "home",
            "close"
          ]
        },
        "list": {
          "description": "Id of the list a page navigation targets. Menus name a list component; a chest menu has one list, so this may be omitted there.",
          "type": "string",
          "minLength": 1
        }
      },
      "allOf": [
        {
          "if": {
            "properties": {
              "mode": {
                "enum": [
                  "back",
                  "home",
                  "close"
                ]
              }
            },
            "required": [
              "mode"
            ]
          },
          "else": {
            "required": [
              "target"
            ]
          }
        }
      ]
    },
    "textIcon": {
      "title": "Text Icon Data Object",
      "description": "Defines the data for a text icon.",
      "type": "object",
      "required": [
        "text"
      ],
      "properties": {
        "text": {
          "description": "Defines the text displayed by this icon. Supports ampersand color codes, placeholders, and line breaks.",
          "type": "string"
        },
        "refreshTicks": {
          "description": "Ticks between live PlaceholderAPI updates. Omitted defaults to 10; 0 disables updates after the initial render.",
          "type": "integer",
          "minimum": 0,
          "maximum": 1200,
          "default": 10
        },
        "box": {
          "description": "Measured text panel and complete perimeter decoration.",
          "$ref": "#/$defs/box"
        }
      }
    },
    "textImageIcon": {
      "title": "Text Image Icon Data Object",
      "description": "Defines the data for a text-image icon.",
      "type": "object",
      "required": [
        "path"
      ],
      "properties": {
        "path": {
          "description": "Defines the path to the image displayed, relative to the \"images\" directory.",
          "type": "string",
          "minLength": 1,
          "pattern": "\\S"
        }
      }
    },
    "animatedTextImageIcon": {
      "title": "Animated Text Image Icon Data Object",
      "description": "Defines the data for an animated text-image icon.",
      "type": "object",
      "required": [
        "source",
        "speed"
      ],
      "properties": {
        "source": {
          "description": "Defines the paths to the animation frames, relative to the \"images\" directory. A single path is accepted in place of the array.",
          "anyOf": [
            {
              "type": "string",
              "minLength": 1,
              "pattern": "\\S"
            },
            {
              "type": "array",
              "minItems": 1,
              "items": {
                "type": "string",
                "minLength": 1,
                "pattern": "\\S"
              }
            }
          ]
        },
        "speed": {
          "description": "Defines the amount of ticks between frame advances.",
          "type": "integer",
          "minimum": 2,
          "maximum": 1200
        }
      }
    },
    "itemIcon": {
      "title": "Item Icon Data Object",
      "description": "Defines the data for an item icon.",
      "type": "object",
      "required": [
        "item"
      ],
      "properties": {
        "item": {
          "description": "Defines the type of item displayed.",
          "type": "string",
          "minLength": 1,
          "pattern": "\\S"
        },
        "count": {
          "description": "Defines the count of the item stack constructed from the material.",
          "type": "integer"
        },
        "customModelValue": {
          "description": "Defines the custom model data property for use with resource packs.",
          "type": "integer"
        },
        "name": {
          "type": "string",
          "description": "Display name for the inventory item. Supports expressions and colors."
        },
        "lore": {
          "type": "array",
          "items": {
            "type": "string"
          },
          "description": "Inventory item lore. Supports expressions and colors."
        },
        "countFormat": {
          "type": "string",
          "default": "&f&l{count}",
          "description": "Stack badge text. Supports {count}, colors and expressions."
        }
      }
    },
    "customItemIcon": {
      "title": "Custom Item Icon Data Object",
      "description": "Defines the data for a custom-item icon resolved through an installed item-provider plugin.",
      "type": "object",
      "required": [
        "item"
      ],
      "properties": {
        "provider": {
          "description": "Defines the item provider that resolves the item. Omitted, blank or \"auto\" tries every active provider in activation order.",
          "type": "string"
        },
        "item": {
          "description": "Defines the provider-specific item id, passed through verbatim.",
          "type": "string",
          "minLength": 1,
          "pattern": "\\S"
        },
        "count": {
          "description": "Defines the count of the resolved item stack. Zero and negative values become 1.",
          "type": "integer"
        },
        "countFormat": {
          "type": "string",
          "default": "&f&l{count}",
          "description": "Stack badge text. Supports {count}, colors and expressions."
        }
      }
    },
    "blockIcon": {
      "title": "Block Icon Data Object",
      "description": "Defines a packet-only block display using the material's default block state. It renders and receives an automatic click plane at 0.75 blocks square before UI and display-style scaling.",
      "type": "object",
      "required": [
        "block"
      ],
      "properties": {
        "block": {
          "description": "Lowercase Bukkit material id. An omitted namespace defaults to minecraft. The resolved material must be a block.",
          "type": "string",
          "pattern": "^([a-z0-9_.-]+:)?[a-z0-9_./-]+$"
        },
        "name": {
          "type": "string",
          "description": "Display name for the inventory item. Supports expressions and colors."
        },
        "lore": {
          "type": "array",
          "items": {
            "type": "string"
          },
          "description": "Inventory item lore. Supports expressions and colors."
        }
      }
    },
    "entityIcon": {
      "title": "Entity Icon Data Object",
      "description": "Defines a packet-only spawnable living entity. The component anchor is the entity's feet; width and height define its automatic click plane and editor footprint in blocks at uiScale 1.",
      "type": "object",
      "required": [
        "entity"
      ],
      "properties": {
        "entity": {
          "description": "Lowercase Bukkit entity registry id. An omitted namespace defaults to minecraft; only spawnable living entity types are accepted.",
          "type": "string",
          "pattern": "^([a-z0-9_.-]+:)?[a-z0-9_./-]+$"
        },
        "width": {
          "description": "Automatic click-plane width in blocks at uiScale 1. Omitted defaults to 1.",
          "type": "number",
          "exclusiveMinimum": 0,
          "maximum": 64,
          "default": 1
        },
        "height": {
          "description": "Automatic click-plane height in blocks at uiScale 1. Omitted defaults to 1 and the plane is centered half this height above the component anchor.",
          "type": "number",
          "exclusiveMinimum": 0,
          "maximum": 64,
          "default": 1
        }
      }
    },
    "playerHeadIcon": {
      "title": "Player Head Icon Data Object",
      "description": "Defines a head rendered from a Minecraft account. The profile is resolved asynchronously and cached; until it lands the icon draws an unowned head, and a name that does not exist draws the configured fallback block instead.",
      "type": "object",
      "required": [
        "player"
      ],
      "properties": {
        "player": {
          "description": "Defines whose head to draw: a literal Minecraft username, or a placeholder resolved per viewer. %player_name%, %player% and {{ player.name }} always mean the viewer and need no PlaceholderAPI; any other placeholder resolves through the text pipeline and needs whatever provides it.",
          "type": "string",
          "minLength": 1,
          "pattern": "\\S"
        },
        "refreshTicks": {
          "description": "Ticks between re-reading the name and the profile cache. Omitted defaults to 20. Zero never re-reads, which leaves a head whose lookup was still in flight as the unowned head.",
          "type": "integer",
          "minimum": 0,
          "maximum": 1200,
          "default": 20
        },
        "name": {
          "type": "string",
          "description": "Display name for the inventory item. Supports expressions and colors."
        },
        "lore": {
          "type": "array",
          "items": {
            "type": "string"
          },
          "description": "Inventory item lore. Supports expressions and colors."
        }
      }
    },
    "box": {
      "type": "object",
      "properties": {
        "enabled": {
          "type": "boolean",
          "default": false
        },
        "padding": {
          "type": "integer",
