    "show": {
      "oneOf": [
        {
          "type": "boolean"
        },
        {
          "type": "string",
          "minLength": 1
        }
      ],
      "description": "Boolean or Gloss boolean expression. Entity variables include entity.name, named, type, health, maxHealth, healthPercent (0..100), damage, damaged, attack, armor, stackCount, distance, and insight.active. Viewer, world, server, time, permissions, groups, regions and integration functions use the shared condition scope."
    },
    "closeAction": {
      "title": "Close Action Data Object",
      "description": "Closes the surface the click came from: a menu session or an inventory window. Terminal.",
      "type": "object",
      "properties": {}
    },
    "inventoryAction": {
      "title": "Inventory Action Data Object",
      "description": "Opens an inventories/ chest menu for the clicking player. Terminal: the window owns the flow from here.",
      "type": "object",
      "required": [
        "id"
      ],
      "properties": {
