          "type": "object",
          "additionalProperties": true
        }
      }
    },
    "setSessionAction": {
      "title": "Set Session Variable Action Data Object",
      "description": "Writes one session variable of the open surface. Continues the list; components whose text or show reads the variable re-render.",
