          "type": "string",
          "minLength": 1
        }
      }
    },
    "listComponent": {
      "title": "List Component Data Object",
      "description": "Repeats one template per entry of a source expression, flowed on a grid. Capped by [menus] maxListEntries.",
      "type": "object",
      "required": [
        "var",
        "source",
