          "type": "string",
          "minLength": 1
        },
        "pageSize": {
          "description": "Entries shown at once; navigate mode page moves between them.",
          "type": "integer",
          "minimum": 1
        },
        "flow": {
          "description": "Grid geometry in menu-local units.",
          "type": "object",
          "properties": {
            "columns": {
              "description": "Entries per row.",
              "type": "integer",
              "minimum": 1
            },
            "spacingX": {
              "description": "Horizontal spacing between entries.",
              "type": "number"
            },
            "spacingY": {
              "description": "Vertical spacing between rows.",
              "type": "number"
            },
            "x": {
              "description": "Horizontal offset of the first entry.",
              "type": "number"
            },
            "y": {
              "description": "Vertical offset of the first entry.",
              "type": "number"
            }
          }
        },
        "template": {
          "description": "The component each entry becomes.",
          "$ref": "#/$defs/componentData"
        }
      }
    },
    "sliderComponent": {
      "title": "Slider Component Data Object",
