          "type": "number",
          "exclusiveMinimum": 0
        },
        "width": {
          "description": "Horizontal click-area width in menu-local units, scaled with the menu.",
          "type": "number",
          "exclusiveMinimum": 0
        },
        "label": {
          "description": "Text drawn for the slider; usually reads session.<var>.",
          "type": "string"
        },
        "style": {
          "$ref": "#/$defs/iconDisplayStyle"
        }
      }
    },
    "fieldComponent": {
      "title": "Field Component Data Object",
