        }
      }
    },
    "promptAction": {
      "title": "Prompt Action Data Object",
      "description": "Asks the player for a line of text in a sign, anvil or chat editor. Terminal: the answer lands in the session variable and then runs, with input.value holding it.",
      "type": "object",
