    "takeAction": {
      "title": "Take Action Data Object",
      "description": "Takes items from the clicking player, all or nothing. Terminal when they do not have them.",
      "type": "object",
      "required": [
        "item"
      ],
      "properties": {
        "item": {
          "description": "The item to take, in icon form.",
          "$ref": "#/$defs/icon"
        },
        "amount": {
          "description": "Expression for how many to take.",
          "type": "string"
        },
        "denyMessage": {
          "description": "Message sent when the player does not have them.",
          "type": "string"
        }
      }
