          "description": "Message sent when the player cannot afford it.",
          "type": "string"
        }
      }
    },
    "actionList": {
      "title": "Action List",
      "description": "An ordered list of actions. Control-flow actions nest their branches and steps through this definition.",
      "type": "array",
      "items": {
        "$ref": "#/$defs/action"
      }
    },
    "delayAction": {
      "title": "Delay Action Data Object",
      "description": "Suspends the surrounding action list and resumes it after the given number of ticks on the player's region thread.",
      "type": "object",
      "required": [
        "ticks"
      ],
      "properties": {
        "ticks": {
          "description": "Ticks to wait before the rest of the list runs.",
          "type": "integer",
          "minimum": 1,
          "maximum": 1728000
        }
      }
    },
    "sequenceAction": {
      "title": "Sequence Action Data Object",
      "description": "A timed list of steps. Each step is an ordinary action that may carry atTicks, its cue measured from the start of the sequence; steps without a cue run with the previous one.",
      "type": "object",
      "required": [
        "steps"
      ],
      "properties": {
        "steps": {
          "description": "The ordered steps. Each entry is an action object that may add an integer atTicks cue.",
          "type": "array",
          "minItems": 1,
          "items": {
            "allOf": [
              {
                "$ref": "#/$defs/action"
              }
            ],
            "properties": {
              "atTicks": {
                "description": "Tick offset from the start of the sequence.",
                "type": "integer",
                "minimum": 0,
                "maximum": 1728000
              }
            }
          }
        },
        "skippable": {
          "description": "When true the viewer ends the sequence by sneaking, which runs onSkip.",
          "type": "boolean",
          "default": false
        },
        "once": {
          "description": "Player boolean state key set when the sequence completes; while it is true the sequence is skipped.",
          "type": "string",
          "pattern": "^[a-z][a-z0-9_.]*$"
        },
        "onSkip": {
          "$ref": "#/$defs/actionList",
          "description": "Actions run when a skippable sequence is ended early."
        }
      }
    },
    "parallelAction": {
      "title": "Parallel Action Data Object",
      "description": "Starts every branch as its own program and continues with the rest of the list immediately.",
      "type": "object",
      "required": [
        "branches"
      ],
      "properties": {
        "branches": {
          "description": "One action list per branch.",
          "type": "array",
          "minItems": 1,
          "items": {
            "$ref": "#/$defs/actionList"
          }
        }
      }
    },
    "repeatAction": {
      "title": "Repeat Action Data Object",
      "description": "Runs steps up to times iterations. With everyTicks the loop suspends between iterations; without it the whole loop runs in one tick and is capped at 1024 iterations.",
      "type": "object",
      "required": [
        "times",
        "steps"
      ],
      "properties": {
        "times": {
          "description": "Maximum number of iterations.",
          "type": "integer",
          "minimum": 1,
          "maximum": 100000
        },
        "everyTicks": {
          "description": "Ticks between iterations. 0 or omitted runs every iteration in the same tick.",
          "type": "integer",
          "minimum": 0,
          "maximum": 1728000,
          "default": 0
        },
        "steps": {
          "$ref": "#/$defs/actionList",
          "description": "The actions run on each iteration."
        },
        "while": {
          "description": "Boolean condition checked before each iteration; false ends the loop early.",
          "type": "string"
        }
      }
    },
    "ifAction": {
      "title": "If Action Data Object",
      "description": "Evaluates when in the action's condition scope and runs then or else.",
      "type": "object",
      "required": [
        "when"
      ],
      "properties": {
        "when": {
          "description": "Boolean condition. Same syntax as show conditions.",
          "type": "string",
          "minLength": 1
        },
        "then": {
          "$ref": "#/$defs/actionList",
          "description": "Actions run when the condition is true."
        },
        "else": {
          "$ref": "#/$defs/actionList",
          "description": "Actions run when the condition is false."
        }
      }
    },
    "switchAction": {
      "title": "Switch Action Data Object",
      "description": "Evaluates on, converts the result to text and runs the matching case, or default when nothing matches.",
      "type": "object",
      "required": [
        "on",
        "cases"
      ],
      "properties": {
        "on": {
          "description": "Expression whose value selects the case.",
          "type": "string",
          "minLength": 1
        },
        "cases": {
          "description": "Case value to action list.",
          "type": "object",
          "minProperties": 1,
          "additionalProperties": {
            "$ref": "#/$defs/actionList"
          }
        },
        "default": {
          "$ref": "#/$defs/actionList",
          "description": "Actions run when no case matches."
        }
      }
    },
    "chanceAction": {
      "title": "Chance Action Data Object",
      "description": "Rolls a percentage and runs then or else.",
