          "minimum": 0,
          "maximum": 100
        },
        "then": {
          "$ref": "#/$defs/actionList",
          "description": "Actions run when the roll succeeds."
        },
        "else": {
          "$ref": "#/$defs/actionList",
          "description": "Actions run when the roll fails."
        }
      }
    },
    "cooldownAction": {
