          "items": {
            "type": "object",
            "properties": {
              "text": {
                "type": "string"
              },
              "width": {
                "type": "integer",
                "minimum": 1,
                "maximum": 1024,
                "default": 200
              }
            }
          }
        },
        "inputs": {
          "type": "array",
          "maxItems": 64,
          "items": {
            "type": "object",
            "required": [
              "key"
            ],
            "properties": {
              "key": {
                "type": "string",
                "pattern": "^[A-Za-z0-9_]{1,64}$"
              },
              "type": {
                "enum": [
                  "text",
                  "boolean",
                  "single_option",
                  "number_range"
                ]
              },
              "label": {
                "type": "string"
              },
