      "required": [
        "action"
      ],
      "properties": {
        "action": {
          "type": "string",
          "pattern": "^[A-Za-z0-9_-]{1,64}$"
        }
      },
      "description": "Runs a named action list from this menu or inventory document, preserving trigger, when and cooldownTicks."
    }
  }
}
