      "maxItems": 6,
      "items": {
        "type": "string",
        "maxLength": 9
      }
    },
    "keys": {
      "type": "object",
      "propertyNames": {
        "minLength": 1,
        "maxLength": 1
      },
      "additionalProperties": {
        "$ref": "#/$defs/component"
      }
    },
    "slots": {
      "type": "object",
      "propertyNames": {
        "pattern": "^[0-9]{1,2}$"
      },
      "additionalProperties": {
        "$ref": "#/$defs/component"
      }
    },
    "list": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "area": {
          "type": "string",
          "minLength": 1,
          "maxLength": 1
        },
        "var": {
          "type": "string"
        },
        "source": true,
        "pageSize": {
          "type": "integer",
          "minimum": 1
        },
        "template": {
          "$ref": "#/$defs/component"
        },
        "refreshTicks": {
          "type": "integer",
          "minimum": 0,
          "maximum": 1200
        }
      }
    },
    "refresh": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "mode": {
          "enum": [
            "dynamic",
            "always"
          ]
        },
        "titleTicks": {
          "type": "integer",
          "minimum": 0,
          "maximum": 1200
        },
        "slotsTicks": {
          "type": "integer",
          "minimum": 0,
          "maximum": 1200
        },
        "conditionsTicks": {
          "type": "integer",
          "minimum": 0,
          "maximum": 1200
        },
        "listTicks": {
          "type": "integer",
          "minimum": 0,
          "maximum": 1200
        }
      }
    },
    "closeOnTeleport": {
      "type": "boolean"
    },
    "show": {
      "$ref": "#/$defs/condition"
