      }
    },
    "variants": {
      "type": "array",
      "items": {
        "type": "object",
        "additionalProperties": false,
        "required": [
          "id"
        ],
        "properties": {
          "id": {
            "type": "string"
          },
          "priority": {
            "type": "integer"
          },
          "when": {
            "type": "string"
          },
          "presentation": {
            "type": "object",
            "additionalProperties": false,
            "properties": {
