            "properties": {
              "amplifier": {
                "type": "integer",
                "minimum": 0,
                "maximum": 255
              },
              "cooldownTicks": true,
              "effect": {
                "type": "string",
                "pattern": "^([a-z0-9_.-]+:)?[a-z0-9_./-]+$"
