              "target": {
                "const": "viewer",
                "description": "subject and source belong to Gloss behaviors and are refused."
              },
              "ticks": {
                "type": "integer",
                "minimum": 1,
                "maximum": 1728000
              },
              "trigger": true,
              "type": true,
              "when": true
            },
            "required": [
