                "description": "A chest window has no location; subject and source belong to Gloss behaviors."
              },
              "cooldownTicks": true,
              "count": {
                "type": "integer",
                "minimum": 1
              },
              "offset": {
                "type": "number",
                "minimum": 0
              },
              "particle": {
                "type": "string",
                "pattern": "^([a-z0-9_.-]+:)?[a-z0-9_./-]+$"
              },
              "trigger": true,
              "type": true,
              "when": true
            },
            "required": [
              "particle"
            ]
          }
        },
        {
          "if": {
            "properties": {
              "type": {
                "const": "parallel"
              }
            }
          },
          "then": {
            "additionalProperties": false,
            "properties": {
              "branches": {
                "type": "array",
                "minItems": 1,
                "items": {
                  "$ref": "#/$defs/actions"
                }
              },
              "cooldownTicks": true,
              "trigger": true,
              "type": true,
              "when": true
            },
            "required": [
              "branches"
            ]
          }
        },
        {
          "if": {
            "properties": {
              "type": {
                "const": "repeat"
              }
            }
          },
          "then": {
            "additionalProperties": false,
            "properties": {
              "cooldownTicks": true,
              "everyTicks": {
                "type": "integer",
                "minimum": 0,
                "maximum": 1728000
              },
              "steps": {
                "$ref": "#/$defs/actions"
              },
              "times": {
                "type": "integer",
                "minimum": 1,
                "maximum": 100000
              },
              "trigger": true,
              "type": true,
              "when": true,
              "while": {
                "type": "string"
              }
            },
            "required": [
              "times",
              "steps"
            ]
          }
        },
        {
          "if": {
            "properties": {
              "type": {
                "const": "animus:open-shop"
              }
            }
          },
          "then": {
            "additionalProperties": false,
            "properties": {
              "cooldownTicks": true,
              "shop": {
                "type": "string",
                "pattern": "^[a-z0-9_-]{1,64}:[a-z0-9_/-]{1,191}$"
              },
              "trigger": true,
              "type": true,
              "when": true
            },
            "required": [
              "shop"
            ]
          }
        }
      ]
    }
  }
}
