  'recording-v1.schema.json': r'''
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://animus.volmitsoftware.com/schema/recording-v1.schema.json",
  "title": "Animus performance recording",
  "description": "recordings/<id>.json. A player's movement captured as frames relative to origin, plus arm swings, equipment changes and door uses. Rules a schema cannot express (frame ticks strictly increasing from 0 to durationTicks, at most durationTicks / sampleTicks + 1 frames, event ticks at most durationTicks, events sorted by tick then type, the id matching the file name, the file at most [recordings] maximumFileBytes) are checked by RecordingDocument; see dev/recording-groups-routes.md.",
  "type": "object",
  "additionalProperties": false,
  "required": ["schemaVersion", "revision", "id", "recordedBy", "world", "origin", "sampleTicks", "durationTicks", "frames", "events"],
  "properties": {
    "schemaVersion": {"const": 1},
    "revision": {"type": "integer", "minimum": 1},
    "id": {"type": "string", "pattern": "^[a-z0-9][a-z0-9_-]{0,63}$", "description": "Matches the file name."},
    "recordedBy": {"type": "string", "pattern": "^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$", "description": "UUID of the player who recorded it."},
    "world": {"type": "string", "minLength": 1, "pattern": "\\S", "description": "The world the recording was made in, as a portable reference: the Bukkit world name or a dimension key such as minecraft:the_nether. The playing server resolves it, or a world UUID, to one of its loaded worlds; a recording whose world is not loaded, or is not the NPC's world, does not play."},
    "origin": {
      "type": "object",
      "additionalProperties": false,
      "required": ["x", "y", "z", "yaw", "pitch"],
      "properties": {
        "x": {"$ref": "#/$defs/coordinate"},
        "y": {"$ref": "#/$defs/coordinate"},
        "z": {"$ref": "#/$defs/coordinate"},
        "yaw": {"$ref": "#/$defs/yaw"},
        "pitch": {"$ref": "#/$defs/pitch"}
      }
    },
    "sampleTicks": {"type": "integer", "minimum": 1, "maximum": 20, "description": "Ticks between two captured frames."},
    "durationTicks": {"type": "integer", "minimum": 1, "maximum": 72000, "description": "The tick of the last frame."},
    "frames": {
      "type": "array",
      "minItems": 2,
      "maxItems": 72001,
      "description": "[tick, dx, dy, dz, yaw, pitch, flags]. Position relative to origin, rounded to 0.01 blocks; absolute yaw and pitch rounded to 0.5 degrees. Flags: 1 onGround, 2 sneaking, 4 sprinting, 8 swimming, 16 gliding, 32 jumping.",
      "items": {
        "type": "array",
        "minItems": 7,
        "maxItems": 7,
        "prefixItems": [
          {"type": "integer", "minimum": 0, "maximum": 72000},
          {"$ref": "#/$defs/offset"},
          {"$ref": "#/$defs/offset"},
          {"$ref": "#/$defs/offset"},
          {"$ref": "#/$defs/yaw"},
          {"$ref": "#/$defs/pitch"},
          {"type": "integer", "minimum": 0, "maximum": 63}
        ]
      }
    },
    "events": {
      "type": "array",
      "maxItems": 4096,
      "items": {"oneOf": [{"$ref": "#/$defs/swing"}, {"$ref": "#/$defs/equipment"}, {"$ref": "#/$defs/use"}]}
    }
  },
  "$defs": {
    "coordinate": {"type": "number", "minimum": -30000000, "maximum": 30000000},
    "offset": {"type": "number", "minimum": -30000000, "maximum": 30000000},
    "yaw": {"type": "number", "minimum": -360, "maximum": 360},
    "pitch": {"type": "number", "minimum": -90, "maximum": 90},
    "tick": {"type": "integer", "minimum": 0, "maximum": 72000},
    "block": {"type": "integer", "minimum": -30000000, "maximum": 30000000},
    "swing": {
      "type": "object",
      "description": "The main arm swung.",
      "additionalProperties": false,
      "required": ["tick", "type"],
      "properties": {"tick": {"$ref": "#/$defs/tick"}, "type": {"const": "swing"}}
    },
    "equipment": {
      "type": "object",
      "description": "A slot changed; item null means the slot was emptied.",
      "additionalProperties": false,
      "required": ["tick", "type", "slot", "item"],
      "properties": {
        "tick": {"$ref": "#/$defs/tick"},
        "type": {"const": "equipment"},
        "slot": {"enum": ["main_hand", "off_hand", "head", "chest", "legs", "feet"]},
        "item": {"oneOf": [{"type": "null"}, {"$ref": "#/$defs/item"}]}
      }
    },
    "use": {
      "type": "object",
      "description": "The recorder opened or closed the door, fence gate or trapdoor at this block.",
      "additionalProperties": false,
      "required": ["tick", "type", "x", "y", "z", "block"],
      "properties": {
        "tick": {"$ref": "#/$defs/tick"},
        "type": {"const": "use"},
        "x": {"$ref": "#/$defs/block"},
        "y": {"$ref": "#/$defs/block"},
        "z": {"$ref": "#/$defs/block"},
        "block": {"type": "string", "maxLength": 128, "pattern": "^[a-z0-9_.-]+:[a-z0-9_./-]+$"}
      }
    },
    "item": {
      "type": "object",
      "additionalProperties": false,
      "required": ["id"],
      "properties": {
        "id": {"type": "string", "maxLength": 128, "pattern": "^[a-z0-9_.-]+:[a-z0-9_./-]+$"},
        "count": {"type": "integer", "minimum": 1, "maximum": 99},
        "components": {"type": "string", "maxLength": 4096, "pattern": "^\\[[\\s\\S]*\\]$"}
      }
    }
  }
}
''',
  'rig-v1.schema.json': r'''
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://animus.volmitsoftware.com/schema/rig-v1.schema.json",
  "title": "Animus rig",
  "description": "rigs/<namespace>/<path>.json. A tree of bones shown as packet-only display entities. Rules a schema cannot express (unique bone ids, parents listed before children, depth at most 16, socket and animation references) are checked by the rig validators; see dev/editor-contracts.md.",
  "type": "object",
  "additionalProperties": false,
  "required": ["schemaVersion", "revision", "id", "bones"],
  "properties": {
    "schemaVersion": {"const": 1},
    "revision": {"type": "integer", "minimum": 1},
    "id": {"$ref": "#/$defs/documentId", "description": "namespace:path, matching this file's location."},
    "units": {"const": "blocks", "description": "Pivots and translations are in blocks. Blockbench pixels are divided by 16 on import."},
    "body": {"enum": ["hidden", "shown"], "description": "hidden: only the rig shows and the hidden body keeps the hitbox. shown: the vanilla body shows and the rig adds parts. Defaults to hidden."},
    "bones": {"type": "array", "minItems": 1, "maxItems": 64, "items": {"$ref": "#/$defs/bone"}},
    "sockets": {
      "type": "object",
      "description": "Equipment slot to bone id.",
      "propertyNames": {"enum": ["main_hand", "off_hand", "head", "chest", "legs", "feet", "body", "saddle"]},
      "additionalProperties": {"$ref": "#/$defs/boneId"}
    },
    "animations": {
      "type": "object",
      "description": "Named animations; idle and walk are switched by navigation.",
      "propertyNames": {"pattern": "^[a-z0-9][a-z0-9_-]{0,63}$"},
      "additionalProperties": {"$ref": "#/$defs/documentId"}
    }
  },
  "$defs": {
    "documentId": {"type": "string", "maxLength": 256, "pattern": "^[a-z0-9_-]{1,64}:[a-z0-9_-]{1,64}(/[a-z0-9_-]{1,64}){0,14}$"},
    "boneId": {"type": "string", "pattern": "^[a-z0-9][a-z0-9_-]{0,63}$"},
    "vector": {"type": "array", "minItems": 3, "maxItems": 3, "items": {"type": "number", "minimum": -1024, "maximum": 1024}},
    "item": {
      "type": "object",
      "additionalProperties": false,
      "required": ["id"],
      "properties": {
        "id": {"type": "string", "pattern": "^[a-z0-9_.-]+:[a-z0-9_./-]+$"},
        "count": {"type": "integer", "minimum": 1, "maximum": 99},
        "components": {"type": "string", "maxLength": 4096, "pattern": "^\\[[\\s\\S]*\\]$"}
      }
    },
    "visual": {
      "type": "object",
      "required": ["type"],
      "properties": {
        "type": {"enum": ["item", "block", "text", "none"]},
        "translation": {"$ref": "#/$defs/vector", "description": "Offset from the bone origin, in blocks, in the bone's space."},
        "rotation": {"$ref": "#/$defs/vector", "description": "Euler degrees in the bone's space, applied X then Y then Z."},
        "scale": {"$ref": "#/$defs/vector"}
      },
      "allOf": [
        {"if": {"properties": {"type": {"const": "item"}}},
         "then": {"required": ["item"], "propertyNames": {"enum": ["type", "translation", "rotation", "scale", "item", "itemDisplay"]},
                  "properties": {"item": {"$ref": "#/$defs/item"},
                                 "itemDisplay": {"enum": ["none", "thirdperson_lefthand", "thirdperson_righthand", "firstperson_lefthand", "firstperson_righthand", "head", "gui", "ground", "fixed"]}}}},
        {"if": {"properties": {"type": {"const": "block"}}},
         "then": {"required": ["block"], "propertyNames": {"enum": ["type", "translation", "rotation", "scale", "block"]},
                  "properties": {"block": {"type": "string", "maxLength": 1024, "pattern": "^[a-z0-9_.-]+:[a-z0-9_./-]+(\\[[^\\]]*\\])?$"}}}},
        {"if": {"properties": {"type": {"const": "text"}}},
         "then": {"required": ["text"], "propertyNames": {"enum": ["type", "translation", "rotation", "scale", "text", "billboard", "background", "shadow", "lineWidth"]},
                  "properties": {"text": {"type": "string", "maxLength": 1024},
                                 "billboard": {"enum": ["fixed", "vertical", "horizontal", "center"]},
                                 "background": {"type": "string", "pattern": "^#[0-9a-fA-F]{8}$"},
                                 "shadow": {"type": "boolean"},
                                 "lineWidth": {"type": "integer", "minimum": 1, "maximum": 1024}}}},
        {"if": {"properties": {"type": {"const": "none"}}},
         "then": {"propertyNames": {"enum": ["type"]}}}
      ]
    },
    "bone": {
      "type": "object",
      "additionalProperties": false,
      "required": ["id", "pivot"],
      "properties": {
        "id": {"$ref": "#/$defs/boneId"},
        "parent": {"$ref": "#/$defs/boneId", "description": "An earlier bone. Bones without a parent hang from the rig origin."},
        "pivot": {"$ref": "#/$defs/vector", "description": "Rest position of the bone origin in rig space, in blocks. Rotations and scales turn about it."},
        "rotation": {"$ref": "#/$defs/vector", "description": "Rest rotation, Euler degrees applied X then Y then Z."},
        "visual": {"$ref": "#/$defs/visual"}
      }
    }
  }
}
''',
  'server-behaviors-v1.schema.json': r'''
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://animus.volmitsoftware.com/schema/server-behaviors-v1.schema.json",
  "title": "Animus server behaviors",
  "description": "server-behaviors.json at the data folder root. Only the server behaviors listed here run. Each id names a behavior with \"server\": true. The Java ServerBehaviorList parser is authoritative.",
  "type": "object",
  "additionalProperties": false,
  "required": ["schemaVersion", "behaviors"],
  "properties": {
    "schemaVersion": {"const": 1, "description": "Always 1."},
    "behaviors": {
      "type": "array",
      "maxItems": 256,
      "uniqueItems": true,
      "description": "Server behaviors to run, at most 256. A missing file runs none; an invalid file runs none until it is fixed.",
      "items": {
        "type": "string",
        "maxLength": 256,
        "pattern": "^[a-z0-9_-]{1,64}:[a-z0-9_-]{1,64}(/[a-z0-9_-]{1,64}){0,14}$",
        "description": "A behavior id, namespace:path, of a behavior with \"server\": true."
      }
    }
  },
  "examples": [{"schemaVersion": 1, "behaviors": ["town:welcome"]}]
}
''',
  'shop-v1.schema.json': r'''
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://animus.volmitsoftware.com/schema/shop-v1.schema.json",
  "title": "Animus shop",
  "description": "shops/<namespace>/<path>.json. The id must equal the file location. The Java ShopDocument parser is authoritative; this schema checks structure for the editor.",
  "type": "object",
  "additionalProperties": false,
  "required": ["schemaVersion", "id", "pages"],
  "properties": {
    "schemaVersion": {"const": 1, "description": "Always 1."},
    "revision": {"type": "integer", "minimum": 1, "description": "Raise this with every edit."},
    "id": {"type": "string", "pattern": "^[a-z0-9_-]{1,64}:[a-z0-9_/-]{1,191}$", "description": "namespace:path, matching this file's location."},
    "title": {"type": "string", "description": "Window title; & codes and MiniMessage. Defaults to the id."},
    "permission": {"$ref": "#/$defs/permission"},
    "modes": {
      "type": "array",
      "minItems": 1,
      "maxItems": 3,
      "items": {"$ref": "#/$defs/mode"},
      "description": "Enabled tabs, each at most once. Defaults to buy, sell and trade."
    },
    "defaultMode": {"$ref": "#/$defs/mode"},
    "match": {"$ref": "#/$defs/match"},
    "closeAfterPurchase": {"type": "boolean"},
    "confirm": {"type": "boolean"},
    "log": {"type": "boolean"},
    "pages": {"type": "array", "minItems": 1, "maxItems": 64, "items": {"$ref": "#/$defs/page"}},
    "imported": {"type": "object", "description": "Preserved source data from an importer."},
    "owner": {
      "type": "object",
      "additionalProperties": false,
